package com.example.ems.upgrade;
import java.sql.*;import java.nio.file.*;import java.util.*;import java.io.*;import java.lang.reflect.*;import java.util.zip.*;
import org.flywaydb.core.Flyway;import org.springframework.jdbc.datasource.DriverManagerDataSource;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
public class Rc2MigrationIT {
 static String base,pw;static final List<String> created=new ArrayList<>();static int checks;
 static void check(boolean ok,String label){if(!ok)throw new AssertionError(label);checks++;System.out.println("PASS: "+label);}
 static String create()throws Exception{String name=(base.contains("ems_next_portable_")?"ems_next_portable_v121_m":base.contains("ems_next_dev_")?"ems_next_dev_v121_m":"ems_next_server_v121_m")+UUID.randomUUID().toString().replace("-","").substring(0,12);try(var c=connection(base);var s=c.createStatement()){s.executeUpdate("CREATE DATABASE "+name+" CHARACTER SET utf8mb4");}created.add(name);return base.replaceFirst("/ems_next_[^?]+","/"+name);}
 static Connection connection(String url)throws SQLException{return DriverManager.getConnection(url,"root",pw);}
 static void migrate(String url)throws Exception{Schema.migrate(url,"root",pw);}
 static long number(Connection c,String sql)throws Exception{try(var s=c.createStatement();var r=s.executeQuery(sql)){r.next();return r.getLong(1);}}
 static String text(Connection c,String sql)throws Exception{try(var s=c.createStatement();var r=s.executeQuery(sql)){r.next();return r.getString(1);}}
 static class Historical extends ClassLoader implements AutoCloseable {
  final ZipFile jar;Historical(Path file)throws IOException{super(Rc2MigrationIT.class.getClassLoader());jar=new ZipFile(file.toFile());}
  protected Class<?> loadClass(String name,boolean resolve)throws ClassNotFoundException{if(!name.startsWith("com.example.ems.upgrade.")&&!name.startsWith("com.example.ems.service.SessionService"))return super.loadClass(name,resolve);synchronized(getClassLoadingLock(name)){Class<?> type=findLoadedClass(name);if(type==null){var entry=jar.getEntry("BOOT-INF/classes/"+name.replace('.','/')+".class");if(entry==null)throw new ClassNotFoundException(name);try(var in=jar.getInputStream(entry)){byte[] b=in.readAllBytes();type=defineClass(name,b,0,b.length);}catch(IOException e){throw new ClassNotFoundException(name,e);}}if(resolve)resolveClass(type);return type;}}
  Object write(Connection c,Path out)throws Exception{return loadClass("com.example.ems.upgrade.Snapshot").getMethod("write",Connection.class,Path.class).invoke(null,c,out);}
  void restoreV2(Connection c,com.fasterxml.jackson.databind.JsonNode manifest,Path staging)throws Exception{loadClass("com.example.ems.upgrade.Snapshot").getMethod("restore",Connection.class,com.fasterxml.jackson.databind.JsonNode.class,Path.class).invoke(null,c,manifest,staging);}
  void loginV2(String url)throws Exception{
   var ds=new org.springframework.jdbc.datasource.DriverManagerDataSource(url,"root",pw);var jdbc=new org.springframework.jdbc.core.JdbcTemplate(ds);Object service=loadClass("com.example.ems.service.SessionService").getConstructor(org.springframework.jdbc.core.JdbcTemplate.class).newInstance(jdbc);var tx=new org.springframework.transaction.support.TransactionTemplate(new org.springframework.jdbc.datasource.DataSourceTransactionManager(ds));
   String token=tx.execute(s->{try{return (String)service.getClass().getMethod("issue",Long.class,String.class).invoke(service,1L,"SyntheticPassword123");}catch(Exception e){throw new IllegalStateException(e);}});check(token!=null&&token.length()==43,"MIG-15 preserved old session code authenticates on restored V2 rollback target");
  }
  void rejectsVersion(String url)throws Exception{var guard=loadClass("com.example.ems.upgrade.SchemaVersionGuard").getConstructor(javax.sql.DataSource.class).newInstance(new DriverManagerDataSource(url,"root",pw));boolean refused=false;try{guard.getClass().getMethod("run",org.springframework.boot.ApplicationArguments.class).invoke(guard,new Object[]{null});}catch(InvocationTargetException e){refused=true;}check(refused,"MIG-14 historical program guard refuses V3 fixture");}
  public void close()throws IOException{jar.close();}
 }
 static void business(Connection c)throws Exception{
  Schema.relations(c);
  check(number(c,"SELECT COUNT(*) FROM employee e JOIN department d ON d.id=e.department_id JOIN position_info p ON p.id=e.position_id WHERE e.id=2 AND p.department_id=d.id")==1,"MIG-02 employee department position relation");
  check(number(c,"SELECT COUNT(*) FROM department d JOIN employee m ON m.id=d.manager_id WHERE d.id=1 AND m.user_type=1 AND m.department_id=d.id")==1,"MIG-02 manager department appointment");
  check(number(c,"SELECT COUNT(*) FROM leave_request l JOIN employee e ON e.id=l.employee_id JOIN employee m ON m.id=l.current_approver_id JOIN department d ON d.id=e.department_id WHERE l.id=1 AND l.employee_id=2 AND m.id=d.manager_id AND l.status=1")==1,"MIG-02 pending leave routes to department manager");
  check(number(c,"SELECT COUNT(*) FROM leave_approval_record a JOIN leave_request l ON l.id=a.leave_request_id JOIN employee e ON e.id=a.approver_id WHERE l.employee_id=2")==1,"MIG-02 leave approval history ownership");
  check(number(c,"SELECT COUNT(*) FROM salary_record s JOIN employee e ON e.id=s.employee_id WHERE e.id=2 AND s.actual_salary=12345.67 AND s.salary_month='2030-01'")==1,"MIG-02 exact salary and employee association");
  check(number(c,"SELECT COUNT(*) FROM attendance_record a JOIN employee e ON e.id=a.employee_id WHERE e.id=2 AND a.attendance_date='2030-01-01'")==1,"MIG-02 attendance employee/date association");
 }
 static void originalLogin(String url)throws Exception{
  var ds=new org.springframework.jdbc.datasource.DriverManagerDataSource(url,"root",pw);var jdbc=new org.springframework.jdbc.core.JdbcTemplate(ds);var auth=new com.example.ems.service.AuthService(jdbc,new com.example.ems.service.LogService(jdbc));var session=new com.example.ems.service.SessionService(jdbc);var tx=new org.springframework.transaction.support.TransactionTemplate(new org.springframework.jdbc.datasource.DataSourceTransactionManager(ds));
  var principal=auth.login("260001","SyntheticPassword123");check(principal.isExecutive(),"MIG-03 restored original executive authenticates with original password and role");
  String token=tx.execute(s->session.issue(principal.id(),"SyntheticPassword123"));check(session.validate(principal.id(),token)==com.example.ems.service.SessionService.Validity.VALID,"MIG-03 final transactional session issuance succeeds after old backup import");
  if(jdbc.queryForObject("SELECT COUNT(*) FROM secondary_credential WHERE employee_id=?",Integer.class,principal.id())==0){
   var request=new org.springframework.mock.web.MockHttpServletRequest();var http=new org.springframework.mock.web.MockHttpSession();http.setAttribute("user",principal);http.setAttribute(com.example.ems.service.SessionService.TOKEN,token);request.setSession(http);org.springframework.web.context.request.RequestContextHolder.setRequestAttributes(new org.springframework.web.context.request.ServletRequestAttributes(request));
   try{var security=new com.example.ems.security.SecurityService(jdbc,session,new com.example.ems.service.LogService(jdbc));tx.execute(s->{security.secondary(principal.id(),"SyntheticPassword123","","MigratedSecondarySetup9");return null;});check(new BCryptPasswordEncoder().matches("MigratedSecondarySetup9",jdbc.queryForObject("SELECT password_hash FROM secondary_credential WHERE employee_id=?",String.class,principal.id())),"MIG-07 restored old executive can set secondary credential without forced first-login setup");}finally{org.springframework.web.context.request.RequestContextHolder.resetRequestAttributes();}
  }
  tx.execute(s->{session.revoke(principal.id(),token);return null;});
 }
 static void enrich(Connection c)throws Exception{try(var s=c.createStatement()){
  s.executeUpdate("INSERT INTO position_info(id,department_id,position_name,position_salary,is_manager_position) VALUES(2,1,'虚构经理岗',2000,1)");
  s.executeUpdate("INSERT INTO employee(id,employee_no,name,identity_number,birth_date,phone,department_id,position_id,user_type,hire_date,employment_status) VALUES(3,'260003','虚构经理','110101199001019997','1990-01-01','13800000003',1,2,1,'2020-01-01',1)");
  s.executeUpdate("INSERT INTO user_account(employee_id,password_hash) SELECT 3,password_hash FROM user_account WHERE employee_id=1");s.executeUpdate("UPDATE user_account SET failed_login_count=2,locked_until='2030-01-01 00:00:00' WHERE employee_id=2");s.executeUpdate("UPDATE user_account SET account_status=0 WHERE employee_id=3");s.executeUpdate("UPDATE department SET manager_id=3 WHERE id=1");s.executeUpdate("UPDATE leave_request SET current_approver_id=3 WHERE id=1");}}
 public static void main(String[] args)throws Exception{
  base=System.getenv("EMS_IT_URL");pw=System.getenv("EMS_IT_PASSWORD");Schema.safeUrl(base);Path work=Path.of(args[0]);Files.createDirectories(work);
  try{
   String source=create();Flyway.configure().dataSource(source,"root",pw).locations("classpath:db/upgrade").target("2").cleanDisabled(true).load().migrate();
   String hash,before;com.fasterxml.jackson.databind.JsonNode beforeBusiness=null;
   try(var c=connection(source)){UpgradeDatabaseIT.seed(c);enrich(c);hash=text(c,"SELECT password_hash FROM user_account WHERE employee_id=2");before=text(c,"SELECT GROUP_CONCAT(CONCAT(version,':',checksum) ORDER BY installed_rank) FROM flyway_schema_history");business(c);}
   // Generate real old-format snapshots with the preserved historical classes, not rc2 masquerading as old code.
   for(int i=1;i<=2;i++){Path oldJar=Path.of(args[i]);try(var historical=new Historical(oldJar);var c=connection(source)){Path raw=work.resolve("old-"+i+".zip");Object oldManifest=historical.write(c,raw);if(i==1)beforeBusiness=Snapshot.JSON.valueToTree(oldManifest).path("tables");Path encrypted=work.resolve("old-"+i+".emsbk"),decoded=work.resolve("old-"+i+"-decoded.zip");BackupCrypto.encrypt(raw,encrypted,"IsolatedMigrationBackup9".toCharArray());BackupCrypto.decrypt(encrypted,decoded,"IsolatedMigrationBackup9".toCharArray());var manifest=Snapshot.inspect(decoded,work.resolve("old-stage-"+i));String target=create();migrate(target);try(var restored=connection(target)){Snapshot.restore(restored,manifest,work.resolve("old-stage-"+i));business(restored);check(text(restored,"SELECT password_hash FROM user_account WHERE employee_id=2").equals(hash),"MIG-03 old password hash unchanged source "+i);check(number(restored,"SELECT COUNT(*) FROM secondary_credential")==0&&number(restored,"SELECT COUNT(*) FROM account_security WHERE frozen=1 OR temporary_state<>'NORMAL'")==0,"MIG-04 old accounts neither frozen nor forced to change");}originalLogin(target);
     String rollback=create();Flyway.configure().dataSource(rollback,"root",pw).locations("classpath:db/upgrade").target("2").cleanDisabled(true).load().migrate();try(var oldTarget=connection(rollback)){historical.restoreV2(oldTarget,manifest,work.resolve("old-stage-"+i));business(oldTarget);check(number(oldTarget,"SELECT COUNT(*) FROM flyway_schema_history WHERE version='3'")==0,"MIG-15 rollback target stays V2 without downgrading a V3 database");}historical.loginV2(rollback);
     check(true,"MIG-07 actual old exporter encrypted backup restored source "+i);}}
   migrate(source);migrate(source);
   try(var c=connection(source)){
    var afterBusiness=Snapshot.JSON.valueToTree(Snapshot.write(c,work.resolve("direct-upgrade-after.zip"))).path("tables");
    var fields=beforeBusiness.fields();while(fields.hasNext()){var oldTable=fields.next();var now=afterBusiness.path(oldTable.getKey());check(oldTable.getValue().path("rows").equals(now.path("rows"))&&oldTable.getValue().path("sha256").equals(now.path("sha256")),"MIG-02 direct upgrade primary-key/all-field digest unchanged: "+oldTable.getKey());}
    check(before.equals(text(c,"SELECT GROUP_CONCAT(CONCAT(version,':',checksum) ORDER BY installed_rank) FROM flyway_schema_history WHERE version IN('1','2')")),"MIG-01 executed V1/V2 checksums unchanged");check(number(c,"SELECT COUNT(*) FROM flyway_schema_history WHERE version='3' AND success=1")==1,"MIG-05 V3 applied exactly once");check(text(c,"SELECT password_hash FROM user_account WHERE employee_id=2").equals(hash),"MIG-03 direct migration preserves hash");business(c);
    var bcrypt=new BCryptPasswordEncoder();try(var s=c.createStatement()){
     try(var tmp=c.prepareStatement("UPDATE user_account SET password_hash=? WHERE employee_id=2")){tmp.setString(1,bcrypt.encode("MigrationTemporary9"));tmp.executeUpdate();}
     s.executeUpdate("INSERT INTO account_security(employee_id,frozen,temporary_state,temporary_expires_at) VALUES(2,1,'TEMP',DATE_ADD(NOW(),INTERVAL 24 HOUR))");
     try(var insert=c.prepareStatement("INSERT INTO secondary_credential(employee_id,password_hash) VALUES(1,?)")){insert.setString(1,bcrypt.encode("SecondaryMigration9"));insert.executeUpdate();}
     s.executeUpdate("INSERT INTO password_change_request(employee_id,active_employee_id,reason,status,approver_id,expires_at) VALUES(2,2,'虚构审批','APPROVED',1,DATE_ADD(NOW(),INTERVAL 30 MINUTE))");
     s.executeUpdate("INSERT INTO account_active_session(employee_id,token_hash) VALUES(2,REPEAT('a',64))");s.executeUpdate("INSERT INTO security_grant(token_hash,employee_id,actor_id,target_id,action,expires_at) VALUES(REPEAT('b',64),2,1,2,'SELF_RESET',DATE_ADD(NOW(),INTERVAL 30 MINUTE)),(REPEAT('c',64),1,1,2,'RESET',DATE_ADD(NOW(),INTERVAL 2 MINUTE))");
     s.executeUpdate("INSERT INTO login_security_event(employee_id,event_type,summary) VALUES(2,'SECURITY_FROZEN','虚构冻结证据')");s.executeUpdate("INSERT INTO security_notification(employee_id,event_type,subject_employee_id,summary,read_at) VALUES(1,'SECURITY_FROZEN',2,'虚构通知',NOW())");
    }
    Snapshot.write(c,work.resolve("v3.zip"));
   }
   BackupCrypto.encrypt(work.resolve("v3.zip"),work.resolve("v3.emsbk"),"MigrationSecurityBackup9".toCharArray());BackupCrypto.decrypt(work.resolve("v3.emsbk"),work.resolve("v3-decoded.zip"),"MigrationSecurityBackup9".toCharArray());
   byte[] corrupt=Files.readAllBytes(work.resolve("v3.emsbk"));corrupt[corrupt.length-1]^=1;Files.write(work.resolve("corrupt.emsbk"),corrupt);boolean corruptRefused=false;try{BackupCrypto.decrypt(work.resolve("corrupt.emsbk"),work.resolve("corrupt.zip"),"MigrationSecurityBackup9".toCharArray());}catch(Exception expected){corruptRefused=true;}check(corruptRefused,"MIG-15 corrupt encrypted backup rejected before import");
   var manifest=Snapshot.inspect(work.resolve("v3-decoded.zip"),work.resolve("v3-stage"));check(manifest.path("schemaVersion").asInt()==3,"MIG-17 snapshot schema version3");
   check(!manifest.path("tables").has("security_grant")&&!manifest.path("tables").has("account_active_session"),"MIG-09 ephemeral authorization/session excluded");
   String restored=create();migrate(restored);try(var c=connection(restored)){Snapshot.restore(c,manifest,work.resolve("v3-stage"));business(c);check(new BCryptPasswordEncoder().matches("SecondaryMigration9",text(c,"SELECT password_hash FROM secondary_credential WHERE employee_id=1")),"MIG-08 secondary hash restored");check(number(c,"SELECT frozen FROM account_security WHERE employee_id=2")==1,"MIG-08 freeze preserved");check("REISSUE".equals(text(c,"SELECT temporary_state FROM account_security WHERE employee_id=2")),"MIG-10 temporary credential cannot revive");check("EXPIRED".equals(text(c,"SELECT status FROM password_change_request WHERE employee_id=2")),"MIG-09 approved reset eligibility expires");check(number(c,"SELECT COUNT(*) FROM security_grant")==0&&number(c,"SELECT COUNT(*) FROM account_active_session")==0,"MIG-09 no reusable authorization or sessions");check(number(c,"SELECT COUNT(*) FROM security_notification WHERE read_at IS NOT NULL")==1&&number(c,"SELECT COUNT(*) FROM login_security_event")==1,"MIG-08 notices/read status and security audit retained");}
   originalLogin(restored);
   try(var c=connection(restored);var s=c.createStatement()){s.executeUpdate("UPDATE account_security SET frozen=0 WHERE employee_id=2");s.executeUpdate("UPDATE user_account SET locked_until=NULL,failed_login_count=0 WHERE employee_id=2");}
   var tempDs=new org.springframework.jdbc.datasource.DriverManagerDataSource(restored,"root",pw);var tempJdbc=new org.springframework.jdbc.core.JdbcTemplate(tempDs);var tempAuth=new com.example.ems.service.AuthService(tempJdbc,new com.example.ems.service.LogService(tempJdbc));check(tempAuth.login("260002","MigrationTemporary9")!=null,"MIG-10 fixture isolates retired temporary hash from other restrictions");
   var tempSessions=new com.example.ems.service.SessionService(tempJdbc);var tempTx=new org.springframework.transaction.support.TransactionTemplate(new org.springframework.jdbc.datasource.DataSourceTransactionManager(tempDs));boolean retired=false;try{tempTx.execute(s->tempSessions.issue(2L,"MigrationTemporary9"));}catch(RuntimeException expected){retired=true;}check(retired,"MIG-10 restored temporary credential cannot issue a session even after other restrictions cleared");
   try(var historical=new Historical(Path.of(args[2]))){historical.rejectsVersion(restored);}
   String failed=create();migrate(failed);Path bad=work.resolve("bad-migration");Files.createDirectory(bad);Files.writeString(bad.resolve("V4__synthetic_failure.sql"),"CREATE TABLE isolated_ddl_sentinel(id BIGINT PRIMARY KEY); INVALID MIGRATION STATEMENT;");boolean refused=false;try{Flyway.configure().dataSource(failed,"root",pw).locations("classpath:db/upgrade","filesystem:"+bad).cleanDisabled(true).load().migrate();}catch(Exception expected){refused=true;}check(refused,"MIG-06 partial DDL failure detected");
   try(var c=connection(failed)){check(Schema.names(c).contains("isolated_ddl_sentinel"),"MIG-06 MySQL DDL not assumed rolled back");}
   boolean startupRefused=false;try{new SchemaVersionGuard(new DriverManagerDataSource(failed,"root",pw)).run(null);}catch(Exception expected){startupRefused=true;}check(startupRefused,"MIG-06 failed migration prevents startup guard");
   String disconnected=create();migrate(disconnected);boolean interrupted=false;
   try(var real=connection(disconnected)){
    long connectionId=number(real,"SELECT CONNECTION_ID()");Connection proxy=(Connection)Proxy.newProxyInstance(Rc2MigrationIT.class.getClassLoader(),new Class[]{Connection.class},(p,m,a)->{if(m.getName().equals("commit")){try(var killer=connection(base);var stmt=killer.createStatement()){stmt.execute("KILL CONNECTION "+connectionId);}}try{return m.invoke(real,a);}catch(InvocationTargetException e){throw e.getCause();}});
    try{Snapshot.restore(proxy,manifest,work.resolve("v3-stage"));}catch(Exception expected){interrupted=true;}
   }check(interrupted,"MIG-15 actual fixture connection interruption detected");
   String recovery=create();migrate(recovery);try(var c=connection(recovery)){Snapshot.restore(c,manifest,work.resolve("v3-stage"));business(c);}check(true,"MIG-15 recovery into another isolated target succeeds after failure");
   boolean space=false;try{Snapshot.requireSpace(1,1024);}catch(IllegalArgumentException e){space=true;}check(space,"MIG-15 injected disk-space preflight rejects without filling disk");
   try(var c=connection(source)){business(c);check(number(c,"SELECT COUNT(*) FROM employee")==3,"MIG-02 source original data retained after all tests");}
   System.out.println("rc2 migration checks passed: "+checks);
  }finally{for(String url:created){String name=url.split("\\?",2)[0];name=name.substring(name.lastIndexOf('/')+1);if(!name.matches("ems_next_(server|portable|dev)_v121_m[a-f0-9]{12}"))throw new IllegalStateException("Unsafe fixture cleanup");try(var c=connection(base);var s=c.createStatement()){s.executeUpdate("DROP DATABASE "+name);}}}
 }
}
